#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    // Start with all bins cleared.
    bins.fill(0);

    // One private histogram per possible worker thread.
    const int max_threads = omp_get_max_threads();
    std::vector<std::array<size_t, 256>> local_bins(static_cast<std::size_t>(max_threads));
    for (auto &hist : local_bins) {
        hist.fill(0);
    }

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        std::array<size_t, 256> &local = local_bins[static_cast<std::size_t>(tid)];

        #pragma omp for schedule(static)
        for (std::size_t i = 0; i < image.size(); ++i) {
            const int pixel = image[i];
            // Input is specified as 0..255; keep a bounds check for robustness.
            if (static_cast<unsigned int>(pixel) < 256u) {
                ++local[static_cast<std::size_t>(pixel)];
            }
        }
    }

    // Reduce thread-local histograms into the output bins serially.
    for (const auto &hist : local_bins) {
        for (std::size_t v = 0; v < 256; ++v) {
            bins[v] += hist[v];
        }
    }
}
